function profileRadius(h) {
  for (let i = 0; i < bodyProfile.length - 1; i++) {
    const [h0, r0] = bodyProfile[i], [h1, r1] = bodyProfile[i + 1];
    if (h >= h0 && h <= h1) {
      const t = (h - h0) / (h1 - h0);
      return r0 + (r1 - r0) * t;
    }
  }
  return h <= bodyProfile[0][0] ? bodyProfile[0][1] : bodyProfile[bodyProfile.length - 1][1];
}

function basisFrom(thetaRad, phi) {
  const n = new THREE.Vector3(Math.sin(thetaRad) * Math.cos(phi), Math.cos(thetaRad), Math.sin(thetaRad) * Math.sin(phi)).normalize();
  const e1 = new THREE.Vector3(Math.cos(thetaRad) * Math.cos(phi), -Math.sin(thetaRad), Math.cos(thetaRad) * Math.sin(phi)).normalize();
  const e2 = new THREE.Vector3(-Math.sin(phi), 0, Math.cos(phi)).normalize();
  return { n, e1, e2 };
}

function localPoint(h, r, a, b) {
  return b.n.clone().multiplyScalar(h)
    .add(b.e1.clone().multiplyScalar(r * Math.cos(a)))
    .add(b.e2.clone().multiplyScalar(r * Math.sin(a)));
}

function createBodyBand(h0, h1, color, opacity, b) {
  const radialSeg = 64, hSeg = 18;
  const verts = [], indices = [];
  for (let i = 0; i <= hSeg; i++) {
    const h = h0 + (h1 - h0) * i / hSeg;
    const r = profileRadius(h);
    for (let j = 0; j <= radialSeg; j++) {
      const a = Math.PI * 2 * j / radialSeg;
      const p = localPoint(h, r, a, b);
      verts.push(p.x, p.y, p.z);
    }
  }
  for (let i = 0; i < hSeg; i++) {
    for (let j = 0; j < radialSeg; j++) {
      const row = radialSeg + 1;
      const a = i * row + j;
      indices.push(a, a + row, a + 1, a + 1, a + row, a + row + 1);
    }
  }
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));
  geom.setIndex(indices);
  geom.computeVertexNormals();
  geom.computeBoundingSphere();
  const mesh = new THREE.Mesh(geom, matBasic(color, { transparent: true, opacity, side: THREE.DoubleSide, depthWrite: false }));
  mesh.renderOrder = 1;
  return mesh;
}

function makeRing(h, r, color, b, dashed = false) {
  const pts = [];
  for (let j = 0; j <= 96; j++) pts.push(localPoint(h, r, Math.PI * 2 * j / 96, b));
  return makeLine(pts, color, { dashed, dashSize: 0.08, gapSize: 0.05, depthTest: false });
}

function horizontalCircle(y, radius, color, opts = {}) {
  const pts = [];
  for (let i = 0; i <= 192; i++) {
    const a = Math.PI * 2 * i / 192;
    pts.push(new THREE.Vector3(radius * Math.cos(a), y, radius * Math.sin(a)));
  }
  return makeLine(pts, color, opts);
}

function arcHorizontal(y, radius, a0, a1, color, opts = {}) {
  const pts = [];
  const steps = 48;
  for (let i = 0; i <= steps; i++) {
    const a = a0 + (a1 - a0) * i / steps;
    pts.push(new THREE.Vector3(radius * Math.cos(a), y, radius * Math.sin(a)));
  }
  return makeLine(pts, color, opts);
}

function arcTheta(thetaRad, phi, radius = 0.62) {
  const pts = [];
  for (let i = 0; i <= 40; i++) {
    const a = thetaRad * i / 40;
    pts.push(new THREE.Vector3(radius * Math.sin(a) * Math.cos(phi), radius * Math.cos(a), radius * Math.sin(a) * Math.sin(phi)));
  }
  return makeLine(pts, AXIS_BLACK, { depthTest: false });
}

function buildSpinArrow(b) {
  const center = b.n.clone().multiplyScalar(2.55);
  const radius = 0.57;
  const pts = [];
  const start = -0.65, end = 4.75;
  for (let i = 0; i <= 92; i++) {
    const a = start + (end - start) * i / 92;
    pts.push(center.clone().add(b.e1.clone().multiplyScalar(radius * Math.cos(a))).add(b.e2.clone().multiplyScalar(radius * Math.sin(a))));
  }
  const line = makeLine(pts, GREEN, { depthTest: false });
  const group = new THREE.Group();
  group.add(line);
  const a = end;
  const tip = center.clone().add(b.e1.clone().multiplyScalar(radius * Math.cos(a))).add(b.e2.clone().multiplyScalar(radius * Math.sin(a)));
  const tangent = b.e1.clone().multiplyScalar(-Math.sin(a)).add(b.e2.clone().multiplyScalar(Math.cos(a))).normalize();
  group.add(addCone(tip, tangent, GREEN, 0.09, 0.20, false));
  return group;
}

const labels = {};
function ensureDynamicLabels() {
  if (labels.cm) return;
  labels.cm = addLabel('CM', new THREE.Vector3(), { fontSize: '16px' });
  labels.r = addLabel('<b>r</b>', new THREE.Vector3(), { fontSize: '15px' });
  labels.theta = addLabel('&theta;', new THREE.Vector3(), { fontSize: '16px' });
  labels.mg = addLabel('<b>M</b><b>g</b>', new THREE.Vector3(), { fontSize: '15px' });
  labels.tau = addLabel('&tau;', new THREE.Vector3(), { fontSize: '16px', color: '#111' });
  labels.tauFormula = addLabel('&tau; = <b>r</b> &times; <b>M</b><b>g</b>', new THREE.Vector3(), { fontSize: '15px' });
  labels.omega = addLabel('&omega;', new THREE.Vector3(), { fontSize: '16px' });
  labels.L = addLabel('<b>L</b>', new THREE.Vector3(), { fontSize: '16px' });
  labels.Lsin = addLabel('<b>L</b> sin&theta;', new THREE.Vector3(), { fontSize: '15px' });
  labels.dphi = addLabel('d&phi;', new THREE.Vector3(), { fontSize: '18px' });
  labels.dL = addLabel('d<b>L</b> = &tau;dt', new THREE.Vector3(), { fontSize: '15px' });
  labels.wp = addLabel('&omega;<sub>p</sub>', new THREE.Vector3(), { fontSize: '16px' });
}

function updateFigure() {
  clearGroup(dynamic);
  const thetaRad = THREE.MathUtils.degToRad(state.tiltAngle);
  const phi = state.phi;
  const b = basisFrom(thetaRad, phi);
  const L = 3.3;
  const Lbase = 1.1;
  const bodyTop = 2.75;
  const stemLen = 1.0;
  const cm = b.n.clone().multiplyScalar(1.85);
  const lTail = b.n.clone().multiplyScalar(Lbase);
  const lTip = lTail.clone().add(b.n.clone().multiplyScalar(L));
  const circleY = lTip.y;
  const circleRadius = Math.max(0.18, Math.sqrt(lTip.x * lTip.x + lTip.z * lTip.z));
  const centerOnAxis = new THREE.Vector3(0, circleY, 0);
  const radialDir = new THREE.Vector3(lTip.x, 0, lTip.z).normalize();
  const tangentDir = new THREE.Vector3(radialDir.z, 0, -radialDir.x).normalize();
  const torqueDir = cm.clone().cross(new THREE.Vector3(0, -1, 0)).normalize();
  if (torqueDir.lengthSq() < 0.1) torqueDir.copy(tangentDir);
  const torqueLen = 0.66 * state.torqueMagnitude;
  const dLLen = 0.52 * state.torqueMagnitude;
  const dPhi = dLLen / Math.max(circleRadius, 0.2);

  dynamic.add(createBodyBand(0, 0.95, BLUE, 0.62, b));
  dynamic.add(createBodyBand(0.95, 1.65, ORANGE_BAND, 0.88, b));
  dynamic.add(createBodyBand(1.65, 2.75, BLUE, 0.64, b));
  dynamic.add(makeRing(0.95, profileRadius(0.95), BLUE_DARK, b));
  dynamic.add(makeRing(1.65, profileRadius(1.65), BLUE_DARK, b));
  dynamic.add(makeRing(bodyTop, profileRadius(bodyTop), BLUE_DARK, b));

  const stemGeom = new THREE.CylinderGeometry(0.22, 0.22, stemLen, 48, 1, false);
  const stem = new THREE.Mesh(stemGeom, matBasic(BLUE, { transparent: true, opacity: 0.74, depthWrite: false }));
  stem.position.copy(b.n.clone().multiplyScalar(bodyTop + stemLen / 2));
  stem.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), b.n);
  stem.renderOrder = 2;
  dynamic.add(stem);
  dynamic.add(makeRing(bodyTop + stemLen, 0.22, BLUE_DARK, b));

  dynamic.add(makeLine([new THREE.Vector3(0, 0, 0), b.n.clone().multiplyScalar(4.0)], AXIS_BLACK, { opacity: 0.55, depthTest: false }));
  dynamic.add(setDepthAlways(makeArrow(new THREE.Vector3(0, 0, 0), cm, AXIS_BLACK, { shaftRadius: 0.022, headRadius: 0.085, headLength: 0.20, depthTest: false })));
  dynamic.add(arcTheta(thetaRad, phi, 0.62));

  const x1a = cm.clone().add(b.e1.clone().add(b.e2).normalize().multiplyScalar(-0.12));
  const x1b = cm.clone().add(b.e1.clone().add(b.e2).normalize().multiplyScalar(0.12));
  const x2a = cm.clone().add(b.e1.clone().sub(b.e2).normalize().multiplyScalar(-0.12));
  const x2b = cm.clone().add(b.e1.clone().sub(b.e2).normalize().multiplyScalar(0.12));
  dynamic.add(makeLine([x1a, x1b], AXIS_BLACK, { depthTest: false }));
  dynamic.add(makeLine([x2a, x2b], AXIS_BLACK, { depthTest: false }));

  dynamic.add(makeArrow(cm, cm.clone().add(new THREE.Vector3(0, -1.25, 0)), RED, { shaftRadius: 0.030, headRadius: 0.11, headLength: 0.25, depthTest: false }));
  dynamic.add(makeArrow(cm, cm.clone().add(torqueDir.clone().multiplyScalar(torqueLen)), ORANGE_VEC, { shaftRadius: 0.032, headRadius: 0.12, headLength: 0.25, depthTest: false }));

  const tauEnd = cm.clone().add(torqueDir.clone().multiplyScalar(torqueLen));
  const formulaPos = cm.clone().add(new THREE.Vector3(1.45, -0.15, -0.62));
  const leaderCurve = new THREE.QuadraticBezierCurve3(
    tauEnd.clone().add(new THREE.Vector3(0.05, -0.04, 0)),
    cm.clone().add(new THREE.Vector3(0.85, -0.78, -0.18)),
    formulaPos.clone().add(new THREE.Vector3(-0.12, 0.0, 0))
  );
  dynamic.add(makeLine(leaderCurve.getPoints(42), AXIS_BLACK, { depthTest: false }));

  dynamic.add(buildSpinArrow(b));
  dynamic.add(makeArrow(lTail, lTip, ORANGE_VEC, { shaftRadius: 0.028, headRadius: 0.13, headLength: 0.28, depthTest: false }));

  dynamic.add(horizontalCircle(circleY, circleRadius, AXIS_BLACK, { dashed: true, dashSize: 0.13, gapSize: 0.075, opacity: 0.9, depthTest: false }));
  const guide = makeLine([centerOnAxis, lTip], AXIS_BLACK, { dashed: true, dashSize: 0.10, gapSize: 0.065, opacity: 0.75, depthTest: false });
  dynamic.add(guide);
  dynamic.add(makeArrow(centerOnAxis, lTip, ORANGE_VEC, { shaftRadius: 0.017, headRadius: 0.10, headLength: 0.22, depthTest: false }));

  const aRad = Math.atan2(lTip.z, lTip.x);
  const arcR = Math.min(0.47, circleRadius * 0.38);
  dynamic.add(arcHorizontal(circleY, arcR, aRad, aRad + dPhi, AXIS_BLACK, { depthTest: false }));
  const dPhiTip = new THREE.Vector3(arcR * Math.cos(aRad + dPhi), circleY, arcR * Math.sin(aRad + dPhi));
  const dPhiTan = new THREE.Vector3(-Math.sin(aRad + dPhi), 0, Math.cos(aRad + dPhi)).normalize();
  dynamic.add(addCone(dPhiTip, dPhiTan, AXIS_BLACK, 0.045, 0.10, false));

  dynamic.add(makeArrow(lTip, lTip.clone().add(tangentDir.clone().multiplyScalar(dLLen)), ORANGE_VEC, { shaftRadius: 0.027, headRadius: 0.12, headLength: 0.24, depthTest: false }));

  const wpStart = aRad + 2.15, wpEnd = aRad + 2.85;
  dynamic.add(arcHorizontal(circleY, circleRadius * 1.03, wpStart, wpEnd, AXIS_BLACK, { depthTest: false }));
  const wpTip = new THREE.Vector3(circleRadius * 1.03 * Math.cos(wpEnd), circleY, circleRadius * 1.03 * Math.sin(wpEnd));
  const wpDir = new THREE.Vector3(-Math.sin(wpEnd), 0, Math.cos(wpEnd)).normalize();
  dynamic.add(addCone(wpTip, wpDir, AXIS_BLACK, 0.075, 0.17, false));

  ensureDynamicLabels();
  labels.cm.pos.copy(cm.clone().add(new THREE.Vector3(-0.18, 0.20, -0.06)));
  labels.r.pos.copy(cm.clone().multiplyScalar(0.54).add(new THREE.Vector3(-0.10, 0.02, 0.03)));
  labels.theta.pos.copy(new THREE.Vector3(0.26 * Math.sin(thetaRad / 2) * Math.cos(phi), 0.77 * Math.cos(thetaRad / 2), 0.26 * Math.sin(thetaRad / 2) * Math.sin(phi)));
  labels.mg.pos.copy(cm.clone().add(new THREE.Vector3(0.22, -0.68, 0.02)));
  labels.tau.pos.copy(cm.clone().add(torqueDir.clone().multiplyScalar(torqueLen * 0.68)).add(new THREE.Vector3(0.08, 0.08, 0)));
  labels.tauFormula.pos.copy(formulaPos);
  labels.omega.pos.copy(b.n.clone().multiplyScalar(2.55).add(b.e1.clone().multiplyScalar(-0.35)).add(b.e2.clone().multiplyScalar(0.10)));
  labels.L.pos.copy(lTail.clone().lerp(lTip, 0.55).add(b.e1.clone().multiplyScalar(0.18)));
  labels.Lsin.pos.copy(centerOnAxis.clone().lerp(lTip, 0.45).add(new THREE.Vector3(0, 0.13, 0)));
  labels.dphi.pos.copy(new THREE.Vector3(0.63 * Math.cos(aRad + dPhi * 0.55), circleY + 0.18, 0.63 * Math.sin(aRad + dPhi * 0.55)));
  labels.dL.pos.copy(lTip.clone().add(tangentDir.clone().multiplyScalar(dLLen + 0.18)).add(new THREE.Vector3(0.10, 0.04, 0)));
  labels.wp.pos.copy(new THREE.Vector3(circleRadius * 1.25 * Math.cos((wpStart + wpEnd) / 2), circleY + 0.05, circleRadius * 1.25 * Math.sin((wpStart + wpEnd) / 2)));

  document.getElementById('tiltAngleVal').textContent = `${Math.round(state.tiltAngle)}°`;
  document.getElementById('torqueMagnitudeVal').textContent = state.torqueMagnitude.toFixed(2);
}

updateFigure();

setCameraView({
