}

function makeArrow(start, end, color, opts = {}) {
  const s = start.clone();
  const e = end.clone();
  const v = e.clone().sub(s);
  const len = v.length();
  const group = new THREE.Group();
  if (len < 1e-6) return group;
  const dir = v.clone().normalize();
  const headLength = opts.headLength ?? Math.min(0.26, len * 0.24);
  const headRadius = opts.headRadius ?? 0.08;
  const shaftRadius = opts.shaftRadius ?? 0.018;
  const shaftLen = Math.max(0.001, len - headLength);
  const material = matBasic(color, { depthTest: opts.depthTest ?? true, depthWrite: opts.depthWrite ?? true });
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(shaftRadius, shaftRadius, shaftLen, 18), material);
  shaft.position.copy(s).add(dir.clone().multiplyScalar(shaftLen / 2));
  shaft.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  group.add(shaft);
  const head = new THREE.Mesh(new THREE.ConeGeometry(headRadius, headLength, 28), material.clone());
  head.position.copy(s).add(dir.clone().multiplyScalar(shaftLen + headLength / 2));
  head.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  group.add(head);
  if (opts.depthTest === false) setDepthAlways(group);
  return group;
}

function makeLine(points, color, opts = {}) {
  const geom = new THREE.BufferGeometry().setFromPoints(points);
