];

function profileRadius(h) {
  for (let i = 0; i < bodyProfile.length - 1; i++) {
    const [h0, r0] = bodyProfile[i];
    const [h1, r1] = bodyProfile[i + 1];
    if (h >= h0 && h <= h1) {
      const t = (h - h0) / (h1 - h0);
      const s = t * t * (3 - 2 * t);
      return r0 + (r1 - r0) * s;
    }
  }
  return h <= bodyProfile[0][0] ? bodyProfile[0][1] : bodyProfile[bodyProfile.length - 1][1];
}

function basisFrom(thetaRad, phi) {
  const n = new THREE.Vector3(
    Math.sin(thetaRad) * Math.cos(phi),
    Math.cos(thetaRad),
    Math.sin(thetaRad) * Math.sin(phi)
  ).normalize();
  const e1 = new THREE.Vector3(
    Math.cos(thetaRad) * Math.cos(phi),
    -Math.sin(thetaRad),
    Math.cos(thetaRad) * Math.sin(phi)
  ).normalize();
  const e2 = new THREE.Vector3(-Math.sin(phi), 0, Math.cos(phi)).normalize();
  return { n, e1, e2 };
}

function localPoint(h, r, a, b) {
  return b.n.clone().multiplyScalar(h)
    .add(b.e1.clone().multiplyScalar(r * Math.cos(a)))
