  labels.omega = addLabel('&omega;', new THREE.Vector3(), { fontSize: '17px', background: 'rgba(255,255,255,0.70)', offset: [-8, -8] });
  labels.L = addLabel('<b>L</b>', new THREE.Vector3(), { fontSize: '17px', background: 'rgba(255,255,255,0.76)', offset: [20, 4] });
  labels.Lsin = addLabel('<b>L</b> sin&theta;', new THREE.Vector3(), { fontSize: '15px', background: 'rgba(255,255,255,0.82)', offset: [-2, -13] });
  labels.dphi = addLabel('d&phi;', new THREE.Vector3(), { fontSize: '18px', background: 'rgba(255,255,255,0.82)', offset: [-10, -17] });
  labels.dL = addLabel('d<b>L</b> = &tau;dt', new THREE.Vector3(), { fontSize: '15px', background: 'rgba(255,255,255,0.82)', offset: [34, 0] });
  labels.wp = addLabel('&omega;<sub>p</sub>', new THREE.Vector3(), { fontSize: '16px', background: 'rgba(255,255,255,0.78)', offset: [-20, -10] });
