const AXIS_BLACK = 0x111111;
const BLUE = 0x62b7cf;
const BLUE_DARK = 0x238ca8;
const ORANGE_BAND = 0xffd37a;
const ORANGE_VEC = 0xf28c00;
const RED = 0xc8324a;
const GREEN = 0x7fa82a;

const state = {
  tiltAngle: 25,
  torqueMagnitude: 0.7,
  phi: 0,
  playing: false
};

const dynamic = new THREE.Group();
scene.add(dynamic);

function disposeObjectLocal(obj) {
  obj.traverse(o => {
    o.geometry?.dispose?.();
    if (Array.isArray(o.material)) o.material.forEach(m => m.dispose?.());
    else o.material?.dispose?.();
  });
}

function clearGroup(g) {
  while (g.children.length) {
    const c = g.children.pop();
    disposeObjectLocal(c);
  }
}

function setDepthAlways(obj) {
  obj.traverse(o => {
    if (o.material) {
      o.material.depthTest = false;
      o.material.depthWrite = false;
    }
    o.renderOrder = 30;
  });
  return obj;
}

function matBasic(color, opts = {}) {
  return new THREE.MeshBasicMaterial({
    color,
    transparent: opts.transparent ?? false,
    opacity: opts.opacity ?? 1,
    side: opts.side ?? THREE.FrontSide,
    depthWrite: opts.depthWrite ?? true,
    depthTest: opts.depthTest ?? true
  });
}

function matTop(color, opts = {}) {
  return new THREE.MeshPhongMaterial({
    color,
    shininess: opts.shininess ?? 38,
    specular: opts.specular ?? 0xe9fbff,
    transparent: opts.transparent ?? false,
    opacity: opts.opacity ?? 1,
    side: opts.side ?? THREE.DoubleSide,
    depthWrite: opts.depthWrite ?? false,
    depthTest: opts.depthTest ?? true
  });
}

function makeArrow(start, end, color, opts = {}) {
  const s = start.clone();
  const e = end.clone();
  const v = e.clone().sub(s);
  const len = v.length();
  const group = new THREE.Group();
  if (len < 1e-6) return group;
  const dir = v.clone().normalize();
  const headLength = opts.headLength ?? Math.min(0.27, len * 0.25);
  const headRadius = opts.headRadius ?? 0.085;
  const shaftRadius = opts.shaftRadius ?? 0.018;
  const shaftLen = Math.max(0.001, len - headLength);
  const material = matBasic(color, { depthTest: opts.depthTest ?? true, depthWrite: opts.depthWrite ?? true });
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(shaftRadius, shaftRadius, shaftLen, 20), material);
  shaft.position.copy(s).add(dir.clone().multiplyScalar(shaftLen / 2));
  shaft.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  group.add(shaft);
  const head = new THREE.Mesh(new THREE.ConeGeometry(headRadius, headLength, 32), material.clone());
  head.position.copy(s).add(dir.clone().multiplyScalar(shaftLen + headLength / 2));
  head.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  group.add(head);
  if (opts.depthTest === false) setDepthAlways(group);
  return group;
}

function makeLine(points, color, opts = {}) {
  const geom = new THREE.BufferGeometry().setFromPoints(points);
  const mat = opts.dashed
    ? new THREE.LineDashedMaterial({
      color,
      dashSize: opts.dashSize ?? 0.12,
      gapSize: opts.gapSize ?? 0.08,
      transparent: opts.opacity != null,
      opacity: opts.opacity ?? 1
    })
    : new THREE.LineBasicMaterial({
      color,
      transparent: opts.opacity != null,
      opacity: opts.opacity ?? 1
    });
  mat.depthTest = opts.depthTest ?? true;
  mat.depthWrite = opts.depthWrite ?? true;
  const line = new THREE.Line(geom, mat);
  if (opts.dashed) line.computeLineDistances();
  if (opts.depthTest === false) setDepthAlways(line);
  return line;
}

function addCone(pos, dir, color, radius = 0.075, length = 0.18, depthTest = true) {
  const cone = new THREE.Mesh(new THREE.ConeGeometry(radius, length, 30), matBasic(color, { depthTest, depthWrite: depthTest }));
  cone.position.copy(pos);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  if (!depthTest) setDepthAlways(cone);
  return cone;
}

function addStaticAxis(end) {
  const a = makeArrow(new THREE.Vector3(0, 0, 0), end, AXIS_BLACK, {
    shaftRadius: 0.010,
    headRadius: 0.060,
    headLength: 0.18
  });
  scene.add(a);
  return a;
}

addStaticAxis(new THREE.Vector3(0, 5.2, 0));
addStaticAxis(new THREE.Vector3(3.5, 0, 0));
addStaticAxis(new THREE.Vector3(0, 0, 2.2));

const bodyProfile = [
  [0.00, 0.00],
  [0.20, 0.10],
  [0.45, 0.32],
  [0.80, 0.65],
  [1.15, 0.92],
  [1.65, 1.15],
  [2.05, 1.12],
  [2.35, 1.05],
  [2.62, 0.87],
  [2.75, 0.75],
  [2.90, 0.68]
];

function profileRadius(h) {
  for (let i = 0; i < bodyProfile.length - 1; i++) {
    const [h0, r0] = bodyProfile[i];
    const [h1, r1] = bodyProfile[i + 1];
    if (h >= h0 && h <= h1) {
      const t = (h - h0) / (h1 - h0);
      const s = t * t * (3 - 2 * t);
      return r0 + (r1 - r0) * s;
    }
  }
  return h <= bodyProfile[0][0] ? bodyProfile[0][1] : bodyProfile[bodyProfile.length - 1][1];
}

function basisFrom(thetaRad, phi) {
  const n = new THREE.Vector3(
    Math.sin(thetaRad) * Math.cos(phi),
    Math.cos(thetaRad),
    Math.sin(thetaRad) * Math.sin(phi)
  ).normalize();
  const e1 = new THREE.Vector3(
    Math.cos(thetaRad) * Math.cos(phi),
    -Math.sin(thetaRad),
    Math.cos(thetaRad) * Math.sin(phi)
  ).normalize();
  const e2 = new THREE.Vector3(-Math.sin(phi), 0, Math.cos(phi)).normalize();
  return { n, e1, e2 };
}

function localPoint(h, r, a, b) {
  return b.n.clone().multiplyScalar(h)
    .add(b.e1.clone().multiplyScalar(r * Math.cos(a)))
    .add(b.e2.clone().multiplyScalar(r * Math.sin(a)));
}

function createBodyBand(h0, h1, color, opacity, b, name) {
  const radialSeg = 96;
  const hSeg = 22;
  const verts = [];
  const indices = [];
  for (let i = 0; i <= hSeg; i++) {
    const h = h0 + (h1 - h0) * i / hSeg;
    const r = profileRadius(h);
    for (let j = 0; j <= radialSeg; j++) {
      const a = Math.PI * 2 * j / radialSeg;
      const p = localPoint(h, r, a, b);
      verts.push(p.x, p.y, p.z);
    }
  }
  for (let i = 0; i < hSeg; i++) {
    for (let j = 0; j < radialSeg; j++) {
      const row = radialSeg + 1;
      const q = i * row + j;
      indices.push(q, q + row, q + 1, q + 1, q + row, q + row + 1);
    }
  }
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));
  geom.setIndex(indices);
  geom.computeVertexNormals();
  geom.computeBoundingSphere();
  const mesh = new THREE.Mesh(geom, matTop(color, {
    transparent: true,
    opacity,
    side: THREE.DoubleSide,
    depthWrite: false,
    shininess: name === 'band' ? 24 : 46,
    specular: name === 'band' ? 0xfff0c0 : 0xdff8ff
  }));
  mesh.renderOrder = name === 'band' ? 3 : 2;
  return mesh;
}

function createDisk(h, r, color, opacity, b) {
  const seg = 112;
  const verts = [];
  const indices = [];
  const c = localPoint(h, 0, 0, b);
  verts.push(c.x, c.y, c.z);
  for (let j = 0; j <= seg; j++) {
    const p = localPoint(h, r, Math.PI * 2 * j / seg, b);
    verts.push(p.x, p.y, p.z);
  }
  for (let j = 1; j <= seg; j++) indices.push(0, j, j + 1);
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));
  geom.setIndex(indices);
  geom.computeVertexNormals();
  const disk = new THREE.Mesh(geom, matTop(color, { transparent: true, opacity, side: THREE.DoubleSide, depthWrite: false, shininess: 48 }));
  disk.renderOrder = 4;
  return disk;
}

function makeRing(h, r, color, b, dashed = false) {
  const pts = [];
  for (let j = 0; j <= 144; j++) pts.push(localPoint(h, r, Math.PI * 2 * j / 144, b));
  return makeLine(pts, color, { dashed, dashSize: 0.08, gapSize: 0.055, depthTest: false });
}

function horizontalCircle(y, radius, color, opts = {}) {
  const pts = [];
  for (let i = 0; i <= 240; i++) {
    const a = Math.PI * 2 * i / 240;
    pts.push(new THREE.Vector3(radius * Math.cos(a), y, radius * Math.sin(a)));
  }
  return makeLine(pts, color, opts);
}

function arcHorizontal(y, radius, a0, a1, color, opts = {}) {
  const pts = [];
  const steps = 58;
  for (let i = 0; i <= steps; i++) {
    const a = a0 + (a1 - a0) * i / steps;
    pts.push(new THREE.Vector3(radius * Math.cos(a), y, radius * Math.sin(a)));
  }
  return makeLine(pts, color, opts);
}

function arcTheta(thetaRad, phi, radius = 0.70) {
  const pts = [];
  for (let i = 0; i <= 48; i++) {
    const a = thetaRad * i / 48;
    pts.push(new THREE.Vector3(
      radius * Math.sin(a) * Math.cos(phi),
      radius * Math.cos(a),
      radius * Math.sin(a) * Math.sin(phi)
    ));
  }
  return makeLine(pts, AXIS_BLACK, { depthTest: false });
}

function buildSpinArrow(b, phase = 0) {
  const center = b.n.clone().multiplyScalar(2.92);
  const radius = 0.54;
  const pts = [];
  const start = -0.85 + phase;
  const end = 4.35 + phase;
  for (let i = 0; i <= 98; i++) {
    const a = start + (end - start) * i / 98;
    pts.push(center.clone()
      .add(b.e1.clone().multiplyScalar(radius * Math.cos(a)))
      .add(b.e2.clone().multiplyScalar(radius * Math.sin(a))));
  }
  const group = new THREE.Group();
  group.add(makeLine(pts, GREEN, { depthTest: false }));
  const a = end;
  const tip = center.clone()
    .add(b.e1.clone().multiplyScalar(radius * Math.cos(a)))
    .add(b.e2.clone().multiplyScalar(radius * Math.sin(a)));
  const tangent = b.e1.clone().multiplyScalar(-Math.sin(a)).add(b.e2.clone().multiplyScalar(Math.cos(a))).normalize();
  group.add(addCone(tip, tangent, GREEN, 0.092, 0.205, false));
  return group;
}

const VEC_R = 'r&#8407;';
const VEC_L = 'L&#8407;';
const VEC_TAU = '&tau;&#8407;';
const VEC_MG = 'M g&#8407;';

const labels = {};
function addAllLabels() {
  if (labels.z) return;
  labels.z = addLabel('z', new THREE.Vector3(0, 5.38, 0), { fontSize: '15px', bold: true, offset: [0, -5] });
  labels.y = addLabel('y', new THREE.Vector3(3.68, 0, 0), { fontSize: '15px', bold: true, offset: [10, 2] });
  labels.x = addLabel('x', new THREE.Vector3(0, -0.02, 2.38), { fontSize: '15px', bold: true, offset: [-8, 12] });
  labels.O = addLabel('<i>O</i>', new THREE.Vector3(0, -0.14, 0), { fontSize: '14px', background: 'rgba(255,255,255,0.72)', offset: [5, 8] });
  labels.cm = addLabel('CM', new THREE.Vector3(), { fontSize: '17px', background: 'rgba(255,255,255,0.72)', offset: [-26, -11] });
  labels.r = addLabel(VEC_R, new THREE.Vector3(), { fontSize: '17px', background: 'rgba(255,255,255,0.62)', offset: [-17, 1] });
  labels.theta = addLabel('&theta;', new THREE.Vector3(), { fontSize: '17px', background: 'rgba(255,255,255,0.65)', offset: [-15, 2] });
  labels.mg = addLabel(VEC_MG, new THREE.Vector3(), { fontSize: '16px', bold: true, background: 'rgba(255,255,255,0.75)', offset: [24, 2] });
  labels.tau = addLabel(VEC_TAU, new THREE.Vector3(), { fontSize: '17px', background: 'rgba(255,255,255,0.75)', offset: [14, -9] });
  labels.tauFormula = addLabel(`${VEC_TAU} = ${VEC_R} &times; ${VEC_MG}`, new THREE.Vector3(), { fontSize: '15px', background: 'rgba(255,255,255,0.84)', offset: [40, 6] });
  labels.omega = addLabel('&omega;', new THREE.Vector3(), { fontSize: '17px', background: 'rgba(255,255,255,0.70)', offset: [-8, -9] });
  labels.L = addLabel(VEC_L, new THREE.Vector3(), { fontSize: '17px', bold: true, background: 'rgba(255,255,255,0.76)', offset: [20, 4] });
  labels.Lsin = addLabel(`${VEC_L} sin&theta;`, new THREE.Vector3(), { fontSize: '15px', background: 'rgba(255,255,255,0.84)', offset: [-10, 18] });
  labels.dphi = addLabel('d&phi;', new THREE.Vector3(), { fontSize: '18px', background: 'rgba(255,255,255,0.86)', offset: [-5, -22] });
  labels.dL = addLabel(`d${VEC_L} = ${VEC_TAU}dt`, new THREE.Vector3(), { fontSize: '15px', background: 'rgba(255,255,255,0.84)', offset: [38, -2] });
  labels.wp = addLabel('&omega;<sub>p</sub>', new THREE.Vector3(), { fontSize: '16px', background: 'rgba(255,255,255,0.78)', offset: [-22, -8] });
}

function updateFigure(updateLabels = true) {
  clearGroup(dynamic);

  const thetaRad = THREE.MathUtils.degToRad(state.tiltAngle);
  const phi = state.phi;
  const b = basisFrom(thetaRad, phi);

  const bodyTop = 2.90;
  const stemLen = 1.00;
  const stemRadius = 0.22;
  const cm = b.n.clone().multiplyScalar(1.85);

  const Llen = 3.30;
  const LbaseVertical = 1.12;
  const lTail = new THREE.Vector3(0, LbaseVertical, 0).add(b.n.clone().multiplyScalar(0.12));
  const lTip = new THREE.Vector3(0, LbaseVertical, 0).add(b.n.clone().multiplyScalar(Llen));
  const circleY = lTip.y;
  const circleRadius = Math.max(0.24, Math.sqrt(lTip.x * lTip.x + lTip.z * lTip.z));
  const centerOnAxis = new THREE.Vector3(0, circleY, 0);
  const radialDir = new THREE.Vector3(lTip.x, 0, lTip.z).normalize();
  const tangentDir = new THREE.Vector3(radialDir.z, 0, -radialDir.x).normalize();

  const torqueDir = cm.clone().cross(new THREE.Vector3(0, -1, 0)).normalize();
  if (torqueDir.lengthSq() < 0.1) torqueDir.copy(tangentDir);
  const torqueLen = 0.68 * state.torqueMagnitude;
  const dLLen = 0.56 * state.torqueMagnitude;
  const dPhi = dLLen / Math.max(circleRadius, 0.25);

  dynamic.add(createBodyBand(0, 0.95, BLUE, 0.64, b, 'lower'));
  dynamic.add(createBodyBand(0.95, 1.65, ORANGE_BAND, 0.90, b, 'band'));
  dynamic.add(createBodyBand(1.65, bodyTop, BLUE, 0.64, b, 'upper'));
  dynamic.add(createDisk(bodyTop, profileRadius(bodyTop), BLUE, 0.58, b));
  dynamic.add(makeRing(0.95, profileRadius(0.95), BLUE_DARK, b));
  dynamic.add(makeRing(1.65, profileRadius(1.65), BLUE_DARK, b));
  dynamic.add(makeRing(bodyTop, profileRadius(bodyTop), BLUE_DARK, b));

  const stemGeom = new THREE.CylinderGeometry(stemRadius, stemRadius, stemLen, 64, 1, false);
  const stem = new THREE.Mesh(stemGeom, matTop(BLUE, { transparent: true, opacity: 0.76, depthWrite: false, shininess: 44 }));
  stem.position.copy(b.n.clone().multiplyScalar(bodyTop + stemLen / 2));
  stem.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), b.n);
  stem.renderOrder = 5;
  dynamic.add(stem);
  dynamic.add(makeRing(bodyTop + stemLen, stemRadius, BLUE_DARK, b));

  dynamic.add(makeLine([new THREE.Vector3(0, 0, 0), b.n.clone().multiplyScalar(bodyTop + stemLen + 0.33)], AXIS_BLACK, { opacity: 0.65, depthTest: false }));
  dynamic.add(makeArrow(new THREE.Vector3(0, 0, 0), cm, AXIS_BLACK, { shaftRadius: 0.027, headRadius: 0.096, headLength: 0.22, depthTest: false }));
  dynamic.add(arcTheta(thetaRad, phi, 0.72));

  const xDiag1 = b.e1.clone().add(b.e2).normalize().multiplyScalar(0.16);
  const xDiag2 = b.e1.clone().sub(b.e2).normalize().multiplyScalar(0.16);
  dynamic.add(makeLine([cm.clone().sub(xDiag1), cm.clone().add(xDiag1)], AXIS_BLACK, { depthTest: false }));
  dynamic.add(makeLine([cm.clone().sub(xDiag2), cm.clone().add(xDiag2)], AXIS_BLACK, { depthTest: false }));

  dynamic.add(makeArrow(cm, cm.clone().add(new THREE.Vector3(0, -1.25, 0)), RED, {
    shaftRadius: 0.033,
    headRadius: 0.116,
    headLength: 0.26,
    depthTest: false
  }));

  dynamic.add(makeArrow(cm, cm.clone().add(torqueDir.clone().multiplyScalar(torqueLen)), ORANGE_VEC, {
    shaftRadius: 0.034,
    headRadius: 0.126,
    headLength: 0.26,
    depthTest: false
  }));

  const tauEnd = cm.clone().add(torqueDir.clone().multiplyScalar(torqueLen));
  const formulaPos = cm.clone()
    .add(torqueDir.clone().multiplyScalar(1.05))
    .add(new THREE.Vector3(0.56, -0.58, -0.55));
  const leaderCurve = new THREE.QuadraticBezierCurve3(
    tauEnd.clone().add(new THREE.Vector3(0.04, -0.02, 0)),
    cm.clone().add(torqueDir.clone().multiplyScalar(0.92)).add(new THREE.Vector3(0.32, -0.84, -0.27)),
    formulaPos.clone().add(new THREE.Vector3(-0.22, 0.02, 0))
  );
  dynamic.add(makeLine(leaderCurve.getPoints(48), AXIS_BLACK, { depthTest: false }));

  dynamic.add(buildSpinArrow(b, state.phi * 4.0));
  dynamic.add(makeArrow(lTail, lTip, ORANGE_VEC, {
    shaftRadius: 0.034,
    headRadius: 0.14,
    headLength: 0.30,
    depthTest: false
  }));

  dynamic.add(horizontalCircle(circleY, circleRadius, AXIS_BLACK, {
    dashed: true,
    dashSize: 0.13,
    gapSize: 0.075,
    opacity: 0.94,
    depthTest: false
  }));
  dynamic.add(makeLine([centerOnAxis, lTip], AXIS_BLACK, {
    dashed: true,
    dashSize: 0.10,
    gapSize: 0.065,
    opacity: 0.78,
    depthTest: false
  }));
  dynamic.add(makeArrow(centerOnAxis, lTip, ORANGE_VEC, {
    shaftRadius: 0.020,
    headRadius: 0.102,
    headLength: 0.23,
    depthTest: false
  }));

  const aRad = Math.atan2(lTip.z, lTip.x);
  const arcR = Math.min(0.46, circleRadius * 0.34);
  dynamic.add(arcHorizontal(circleY, arcR, aRad, aRad + dPhi, AXIS_BLACK, { depthTest: false }));
  const dPhiTip = new THREE.Vector3(arcR * Math.cos(aRad + dPhi), circleY, arcR * Math.sin(aRad + dPhi));
  const dPhiTan = new THREE.Vector3(-Math.sin(aRad + dPhi), 0, Math.cos(aRad + dPhi)).normalize();
  dynamic.add(addCone(dPhiTip, dPhiTan, AXIS_BLACK, 0.047, 0.105, false));

  dynamic.add(makeArrow(lTip, lTip.clone().add(tangentDir.clone().multiplyScalar(dLLen)), ORANGE_VEC, {
    shaftRadius: 0.030,
    headRadius: 0.123,
    headLength: 0.25,
    depthTest: false
  }));

  const wpStart = aRad + 2.25;
  const wpEnd = aRad + 3.05;
  dynamic.add(arcHorizontal(circleY, circleRadius * 1.05, wpStart, wpEnd, AXIS_BLACK, { depthTest: false }));
  const wpTip = new THREE.Vector3(circleRadius * 1.05 * Math.cos(wpEnd), circleY, circleRadius * 1.05 * Math.sin(wpEnd));
  const wpDir = new THREE.Vector3(-Math.sin(wpEnd), 0, Math.cos(wpEnd)).normalize();
  dynamic.add(addCone(wpTip, wpDir, AXIS_BLACK, 0.078, 0.18, false));

  if (updateLabels && labels.cm) {
    labels.cm.pos.copy(cm.clone().add(new THREE.Vector3(-0.10, 0.25, 0.03)));
    labels.r.pos.copy(cm.clone().multiplyScalar(0.49).add(new THREE.Vector3(-0.08, -0.02, 0.02)));
    labels.theta.pos.copy(new THREE.Vector3(
      0.54 * Math.sin(thetaRad * 0.50) * Math.cos(phi),
      0.72 * Math.cos(thetaRad * 0.50),
      0.54 * Math.sin(thetaRad * 0.50) * Math.sin(phi)
    ));
    labels.mg.pos.copy(cm.clone().add(new THREE.Vector3(0.22, -0.93, 0.02)));
    labels.tau.pos.copy(cm.clone().add(torqueDir.clone().multiplyScalar(torqueLen * 0.72)).add(new THREE.Vector3(0.05, 0.10, 0)));
    labels.tauFormula.pos.copy(formulaPos);
    labels.omega.pos.copy(b.n.clone().multiplyScalar(2.90).add(b.e1.clone().multiplyScalar(-0.42)).add(b.e2.clone().multiplyScalar(0.08)));
    labels.L.pos.copy(lTail.clone().lerp(lTip, 0.64).add(b.e1.clone().multiplyScalar(0.15)));
    labels.Lsin.pos.copy(centerOnAxis.clone().lerp(lTip, 0.50).add(new THREE.Vector3(0, -0.055, 0)).add(tangentDir.clone().multiplyScalar(-0.12)));
    labels.dphi.pos.copy(new THREE.Vector3(
      (arcR + 0.20) * Math.cos(aRad + dPhi * 0.52),
      circleY + 0.11,
      (arcR + 0.20) * Math.sin(aRad + dPhi * 0.52)
    ));
    labels.dL.pos.copy(lTip.clone().add(tangentDir.clone().multiplyScalar(dLLen + 0.17)).add(new THREE.Vector3(0.06, 0.06, 0)));
    labels.wp.pos.copy(new THREE.Vector3(
      circleRadius * 1.26 * Math.cos((wpStart + wpEnd) / 2),
      circleY + 0.06,
      circleRadius * 1.26 * Math.sin((wpStart + wpEnd) / 2)
    ));
  }

  document.getElementById('tiltAngleVal').textContent = `${Math.round(state.tiltAngle)}°`;
  document.getElementById('torqueMagnitudeVal').textContent = state.torqueMagnitude.toFixed(2);
}

updateFigure(false);

setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 5, z: 50 },
  rollDeg: 0,
  heightFraction: 0.72,
  distanceScale: 1.15
});

addAllLabels();
updateFigure(true);

registerInteractive(dynamic, {
  title: 'Precessing top geometry',
  tooltip: 'Click for the vector idea',
  body: 'The torque τ⃗ is perpendicular to L⃗, so it changes the direction of angular momentum. The tip of L⃗ moves around the horizontal dashed circle instead of making L⃗ simply grow longer.'
});

const tiltInput = document.getElementById('tiltAngle');
const torqueInput = document.getElementById('torqueMagnitude');
const playButton = document.getElementById('precessionMotion');
const narration = document.getElementById('stepNarration');

tiltInput.addEventListener('input', () => {
  state.tiltAngle = Number(tiltInput.value);
  updateFigure(true);
});

torqueInput.addEventListener('input', () => {
  state.torqueMagnitude = Number(torqueInput.value);
  updateFigure(true);
});

playButton.addEventListener('click', () => {
  state.playing = !state.playing;
  playButton.textContent = state.playing ? 'Pause precession' : 'Play precession';
});

const demoSteps = [
  {
    title: 'Default precessing top',
    narration: 'The top leans by about 25°. The orange L vector lies along the tilted axis and its tip sits on the dashed precession circle.',
    state: { tiltAngle: 25, torqueMagnitude: 0.7 }
  },
  {
    title: 'Increase the tilt',
    narration: 'As θ grows, the dashed circle and the L sinθ construction become wider. The same length L now sweeps a larger radius around the vertical axis.',
    state: { tiltAngle: 40, torqueMagnitude: 0.7 }
  },
  {
    title: 'Increase the torque',
    narration: 'With θ fixed, increasing |τ| lengthens the tangential dL = τdt arrow. The L vector remains the same length, showing that the torque turns L rather than stretching it.',
    state: { tiltAngle: 25, torqueMagnitude: 1.2 }
  }
];

function setActiveStep(i) {
  for (let k = 0; k < 3; k++) document.getElementById(`step${k}`).classList.toggle('active', k === i);
}

function goToStep(i) {
  const step = demoSteps[i];
  if (!step) return;
  setActiveStep(i);
  const startTilt = state.tiltAngle;
  const startTorque = state.torqueMagnitude;
  const endTilt = step.state.tiltAngle;
  const endTorque = step.state.torqueMagnitude;
  const t0 = performance.now();
  narration.innerHTML = `<b>${step.title}</b><br>${step.narration}`;

  function tween(now) {
    const u = Math.min(1, (now - t0) / 650);
    const e = u < 0.5 ? 2 * u * u : 1 - Math.pow(-2 * u + 2, 2) / 2;
    state.tiltAngle = startTilt + (endTilt - startTilt) * e;
    state.torqueMagnitude = startTorque + (endTorque - startTorque) * e;
    tiltInput.value = state.tiltAngle;
    torqueInput.value = state.torqueMagnitude;
    updateFigure(true);
    if (u < 1) requestAnimationFrame(tween);
  }
  requestAnimationFrame(tween);
}

window.goToStep = goToStep;
document.getElementById('step0').addEventListener('click', () => goToStep(0));
document.getElementById('step1').addEventListener('click', () => goToStep(1));
document.getElementById('step2').addEventListener('click', () => goToStep(2));
goToStep(0);

let lastLocalFrame = performance.now();
function precessionLoop(now) {
  const dt = Math.min(0.05, (now - lastLocalFrame) / 1000);
  lastLocalFrame = now;
  if (state.playing) {
    state.phi += dt * 0.34;
    updateFigure(true);
  }
  requestAnimationFrame(precessionLoop);
}
requestAnimationFrame(precessionLoop);
